from typing import *
import heapq as hq


class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        m, n = len(grid), len(grid[0])

        # Create a list of tuples where each tuple contains the diagonal index (i + j) and the value at that position
        heap = []
        for i in range(m):
            for j in range(n):
                hq.heappush(heap, (i + j, grid[i][j]))

        # Sort the heap based on the diagonal index in descending order
        hq.heapify(heap)

        # Pop elements from the heap and place them back into the grid
        result = [[0] * n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                result[i][j] = hq.heappop(heap)[1]

        return result

def find_subgrid(S, T):
    N, M = len(S), len(T)

    for a in range(N - M + 1):
        for b in range(N - M + 1):
            if all(S[a+i-1][b+j-1] == T[i][j] for i in range(M) for j in range(M)):
                return a + 1, b + 1

    raise ValueError("No matching subgrid found")

