def find_subgrid(S, T):
    N, M = len(S), len(T)

    for a in range(N - M + 1):
        for b in range(N - M + 1):
            match = True
            for i in range(M):
                for j in range(M):
                    if S[a + i][b + j] != T[i][j]:
                        match = False
                        break
                if not match:
                    break
            if match:
                return a + 1, b + 1

    return None, None

