def min_front_kicks(H, W, grid, start_row, start_col, end_row, end_col):
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def is_valid(x, y):
        return 1 <= x <= H and 1 <= y <= W

    def bfs(start_row, start_col):
        queue = deque([(start_row, start_col)])
        visited = set()
        visited.add((start_row, start_col))

        while queue:
            row, col = queue.popleft()

            if row == end_row and col == end_col:
                return 0

            for dx, dy in directions:
                nx, ny = row + dx, col + dy

                if is_valid(nx, ny) and grid[nx][ny] == '.' and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny))

        return float('inf')

    front_kicks = 0

    while True:
        current_row, current_col = start_row, start_col
        min_steps = float('inf')

        for dx, dy in directions:
            nx, ny = current_row + dx, current_col + dy

            if is_valid(nx, ny) and grid[nx][ny] == '#':
                min_steps = min(min_steps, bfs(current_row, current_col))

        if min_steps == float('inf'):
            break

        front_kicks += min_steps

    return front_kicks

# Read input
H, W = map(int, input().split())
grid = [input() for _ in range(H)]
start_row, start_col, end_row, end_col = map(int, input().split())

# Solve the problem
min_kicks = min_front_kicks(H, W, grid, start_row, start_col, end_row, end_col)
print(min_kicks)

import sys

def find_column_count(rows):
    if rows == 1:
        return 1
    # Find the smallest integer b such that rows * b = 400
    b = 400 // rows
    # Check if the division is exact
    if rows * b == 400:
        return b
    else:
        return -1

