class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x != root_y:
            self.parent[root_x] = root_y

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        uf = UnionFind(n)
        graph = defaultdict(list)
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        def dfs(node, parent):
            for neighbor, weight in graph[node]:
                if neighbor != parent and uf.find(neighbor) != uf.find(parent):
                    uf.union(neighbor, parent)
                    dfs(neighbor, parent)

        # Remove edges with weight less than or equal to threshold
        for i in range(n):
            for j in range(i + 1, n):
                if graph[i][j][1] > threshold:
                    uf.union(i, j)

        # Find the largest connected component size
        max_size = 0
        for i in range(n):
            if uf.find(i) == i:
                max_size = max(max_size, len(graph[i]))

        if max_size <= threshold:
            return -1

        # Check if we can remove any edge to make all components connected
        visited = set()
        for i in range(n):
            if uf.find(i) not in visited:
                visited.add(uf.find(i))
                queue = deque([i])
                while queue:
                    node = queue.popleft()
                    for neighbor, _ in graph[node]:
                        if uf.find(neighbor) not in visited:
                            visited.add(uf.find(neighbor))
                            queue.append(neighbor)

        return max_size - 1

class Solution:
    def hasSameDigits(self, s: str) -> bool:
        while len(s) > 2:
            s = str(sum(int(digit) for digit in s)) % 10

        return int(s[-1]) == int(s[-2])

